SELECT
FROM appointment a JOIN schedule s ON s.id = a.schedule_id JOIN doctor d ON d.id = s.doctor_id JOIN department dep ON dep.id = d.department_id LEFT JOIN prescription p ON p.appointment_id = a.id
AND (a.patient_name LIKE CONCAT('%', #{keyword}, '%') OR a.patient_phone LIKE CONCAT('%', #{keyword}, '%'))
AND a.status = #{status}
AND s.schedule_date = #{scheduleDate}
ORDER BY s.schedule_date DESC, s.time_slot DESC, a.id DESC

SELECT id FROM appointment
WHERE status = 'unpaid' AND pay_time IS NULL AND create_time <= #{cutoff}
  AND id > #{afterId}
ORDER BY id LIMIT #{limit}

SELECT COUNT(*) FROM balance_log
WHERE user_id=#{appointment.userId} AND order_id=#{appointment.id}
AND type='mock_order_pay' AND amount=#{appointment.amount}
AND pay_method=#{appointment.payMethod} AND remark='学习模拟挂号付款'
